changeSet.sql:
CREATE TABLE courier_store_visits (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    courier_id TEXT NOT NULL REFERENCES couriers (courier_id) ON DELETE CASCADE,
    store_name TEXT NOT NULL,
    entry_time TIMESTAMP(3) WITH TIME ZONE NOT NULL,
    exit_time TIMESTAMP(3) WITH TIME ZONE,
    created_at TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT now(),
    updated_at TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT now(),
    CONSTRAINT ck_store_visit_exit_after_entry CHECK (exit_time IS NULL OR exit_time > entry_time)
);

CREATE UNIQUE INDEX uq_store_visit_open ON courier_store_visits (courier_id, store_name) WHERE exit_time IS NULL;
CREATE INDEX ix_courier_store_visits_courier_store_entry ON courier_store_visits (courier_id, store_name, entry_time DESC);
